// <auto-generated/>
// Round-trip serialization tests for Nalix TypeScript packets

import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as P from '../src/array-probe.js';

test('ArrayProbe round-trip binary serialization', () => {
  const pkt = new P.ArrayProbe();
  pkt.header.opcode = P.ArrayProbe.OPCODE;
  pkt.header.sequenceId = 42;
  pkt.token.fill(0x5a);
  pkt.ids = [new Uint8Array(16).fill(0x5a)];
  pkt.tags = ['test-string-payload'];
  pkt.scores = [42, 7];
  pkt.big = [123456789012345678n, 42n];
  pkt.flags = [true, false];
  pkt.ratio = [42, 7];
  pkt.raw = new Uint8Array([1, 2, 3, 0xfe]);
  pkt.title = 'test-string-payload';
  pkt.key.fill(0x5a);
  const encoded = pkt.encode();
  assert.ok(encoded.byteLength >= P.ArrayProbe.FIXED_SIZE);
  const decoded = P.ArrayProbe.decode(encoded);
  assert.equal(decoded.header.opcode, P.ArrayProbe.OPCODE);
  assert.equal(decoded.header.sequenceId, 42);
  assert.deepEqual(decoded.token, pkt.token);
  assert.deepEqual(decoded.ids, pkt.ids);
  assert.deepEqual(decoded.tags, pkt.tags);
  assert.deepEqual(decoded.scores, pkt.scores);
  assert.deepEqual(decoded.big, pkt.big);
  assert.deepEqual(decoded.flags, pkt.flags);
  assert.deepEqual(decoded.ratio, pkt.ratio);
  assert.deepEqual(decoded.raw, pkt.raw);
  assert.equal(decoded.title, pkt.title);
  assert.deepEqual(decoded.key, pkt.key);
});

